-- The tables of the project, for Oracle 12c or later.
-- Generated by ElastiCORE from the model, in the column types that database's Hibernate dialect would
-- choose. Run it with spring.sql.init.schema-locations on an empty database.

CREATE SEQUENCE revinfo_seq START WITH 1 INCREMENT BY 50;

CREATE TABLE cms_article (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    article_id VARCHAR2(36 CHAR) NOT NULL,
    title VARCHAR2(300 CHAR) NOT NULL,
    slug VARCHAR2(300 CHAR) NOT NULL,
    summary VARCHAR2(500 CHAR),
    body CLOB,
    body_text CLOB,
    publish_date TIMESTAMP(6),
    view_count NUMBER(19),
    featured NUMBER(1),
    article_status VARCHAR2(3 CHAR),
    ratings VARCHAR2(255 CHAR),
    labels VARCHAR2(255 CHAR),
    category_category_id NUMBER(19),
    PRIMARY KEY (article_id)
);

CREATE TABLE cms_article_tags (
    article_article_id VARCHAR2(36 CHAR) NOT NULL,
    tags_tag_id NUMBER(19) NOT NULL
);

CREATE TABLE cms_article_aud (
    rev NUMBER(10) NOT NULL,
    revtype NUMBER(3),
    article_id VARCHAR2(36 CHAR) NOT NULL,
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    title VARCHAR2(300 CHAR),
    slug VARCHAR2(300 CHAR),
    summary VARCHAR2(500 CHAR),
    body CLOB,
    body_text CLOB,
    publish_date TIMESTAMP(6),
    view_count NUMBER(19),
    featured NUMBER(1),
    article_status VARCHAR2(3 CHAR),
    ratings VARCHAR2(255 CHAR),
    labels VARCHAR2(255 CHAR),
    category_category_id NUMBER(19),
    PRIMARY KEY (article_id, rev)
);

CREATE TABLE cms_attachment (
    attach_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    file_name VARCHAR2(255 CHAR) NOT NULL,
    file_size NUMBER(19),
    content_type VARCHAR2(100 CHAR),
    storage_key VARCHAR2(500 CHAR),
    article_article_id VARCHAR2(36 CHAR),
    PRIMARY KEY (attach_id)
);

CREATE TABLE cms_bookmark (
    bookmark_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    memo VARCHAR2(200 CHAR),
    article_article_id VARCHAR2(36 CHAR),
    PRIMARY KEY (bookmark_id)
);

CREATE TABLE cms_comment (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    comment_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    content CLOB NOT NULL,
    author_name VARCHAR2(100 CHAR) NOT NULL,
    author_email VARCHAR2(100 CHAR),
    approved NUMBER(1),
    test_id NUMBER(19),
    article_article_id VARCHAR2(36 CHAR),
    PRIMARY KEY (comment_id)
);

CREATE TABLE cms_content_category (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    category_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(100 CHAR) NOT NULL,
    slug VARCHAR2(100 CHAR) NOT NULL,
    description CLOB,
    sort_order NUMBER(10),
    parent_category_id NUMBER(19),
    PRIMARY KEY (category_id)
);

CREATE TABLE cms_tag (
    tag_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(50 CHAR) NOT NULL,
    color VARCHAR2(7 CHAR),
    PRIMARY KEY (tag_id)
);

CREATE TABLE revinfo (
    rev NUMBER(10) NOT NULL,
    revtstmp NUMBER(19) NOT NULL,
    PRIMARY KEY (rev)
);

CREATE TABLE hr_department (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    version NUMBER(19),
    dept_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    code VARCHAR2(10 CHAR) NOT NULL,
    name VARCHAR2(100 CHAR) NOT NULL,
    name_insensitive VARCHAR2(100 CHAR),
    description CLOB,
    budget NUMBER(14,2),
    head_count NUMBER(10),
    max_capacity NUMBER(10),
    floor_number NUMBER(10),
    min_salary NUMBER(10,2),
    status VARCHAR2(1 CHAR),
    name_prefix VARCHAR2(50 CHAR),
    name_suffix VARCHAR2(50 CHAR),
    name_prefix_ci VARCHAR2(50 CHAR),
    name_suffix_ci VARCHAR2(50 CHAR),
    name_exact_ci VARCHAR2(50 CHAR),
    active NUMBER(1),
    internal_code VARCHAR2(30 CHAR),
    external_code VARCHAR2(30 CHAR),
    legacy_code VARCHAR2(30 CHAR),
    PRIMARY KEY (dept_id)
);

CREATE TABLE hr_employee (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    version NUMBER(19),
    emp_id VARCHAR2(36 CHAR) NOT NULL,
    first_name VARCHAR2(50 CHAR) NOT NULL,
    last_name VARCHAR2(50 CHAR) NOT NULL,
    email VARCHAR2(100 CHAR) NOT NULL,
    phone VARCHAR2(20 CHAR),
    hire_date DATE NOT NULL,
    salary NUMBER(12,2) NOT NULL,
    bonus_rate BINARY_DOUBLE,
    active NUMBER(1),
    manager_emp_id VARCHAR2(36 CHAR),
    department_dept_id NUMBER(19),
    PRIMARY KEY (emp_id)
);

CREATE TABLE hr_employee_skills (
    employee_emp_id VARCHAR2(36 CHAR) NOT NULL,
    skills_skill_id NUMBER(19) NOT NULL
);

CREATE TABLE hr_employee_aud (
    rev NUMBER(10) NOT NULL,
    revtype NUMBER(3),
    emp_id VARCHAR2(36 CHAR) NOT NULL,
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    version NUMBER(19),
    first_name VARCHAR2(50 CHAR),
    last_name VARCHAR2(50 CHAR),
    email VARCHAR2(100 CHAR),
    phone VARCHAR2(20 CHAR),
    hire_date DATE,
    salary NUMBER(12,2),
    bonus_rate BINARY_DOUBLE,
    active NUMBER(1),
    manager_emp_id VARCHAR2(36 CHAR),
    department_dept_id NUMBER(19),
    PRIMARY KEY (emp_id, rev)
);

CREATE TABLE hr_project (
    project_code VARCHAR2(20 CHAR) NOT NULL,
    name VARCHAR2(100 CHAR) NOT NULL,
    start_date DATE,
    end_date DATE,
    budget NUMBER(14,2),
    status VARCHAR2(3 CHAR),
    PRIMARY KEY (project_code)
);

CREATE TABLE hr_project_assignment (
    emp_id VARCHAR2(36 CHAR) NOT NULL,
    project_code VARCHAR2(20 CHAR) NOT NULL,
    role VARCHAR2(50 CHAR),
    assign_date DATE,
    hours_allocated NUMBER(10),
    PRIMARY KEY (emp_id, project_code)
);

CREATE TABLE hr_skill (
    skill_name VARCHAR2(100 CHAR) NOT NULL,
    proficiency NUMBER(10),
    skill_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    category VARCHAR2(50 CHAR),
    PRIMARY KEY (skill_id)
);

CREATE TABLE intg_api_log (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    inherited_payment_method VARCHAR2(2 CHAR),
    log_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    endpoint VARCHAR2(500 CHAR) NOT NULL,
    method VARCHAR2(10 CHAR) NOT NULL,
    request_body CLOB,
    response_body CLOB,
    status_code NUMBER(10),
    duration NUMBER(19),
    created_at TIMESTAMP(6),
    related_order_status VARCHAR2(3 CHAR),
    PRIMARY KEY (log_id)
);

CREATE TABLE intg_sync_record (
    record_id VARCHAR2(36 CHAR) NOT NULL,
    source_system VARCHAR2(50 CHAR) NOT NULL,
    target_system VARCHAR2(50 CHAR) NOT NULL,
    entity_type VARCHAR2(50 CHAR),
    entity_id VARCHAR2(100 CHAR),
    sync_status VARCHAR2(3 CHAR),
    sync_date TIMESTAMP(6),
    error_message CLOB,
    retry_count NUMBER(10),
    PRIMARY KEY (record_id)
);

CREATE TABLE blog_post (
    id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    title VARCHAR2(200 CHAR) NOT NULL,
    content CLOB,
    summary VARCHAR2(500 CHAR),
    status VARCHAR2(20 CHAR),
    view_count NUMBER(10),
    author VARCHAR2(100 CHAR) NOT NULL,
    published_at TIMESTAMP(6),
    modified_at TIMESTAMP(6),
    PRIMARY KEY (id)
);

CREATE TABLE member (
    id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    username VARCHAR2(50 CHAR) NOT NULL,
    password VARCHAR2(200 CHAR),
    email VARCHAR2(100 CHAR) NOT NULL,
    nickname VARCHAR2(50 CHAR),
    role VARCHAR2(20 CHAR),
    login_count NUMBER(10),
    last_login_at TIMESTAMP(6),
    bio VARCHAR2(500 CHAR),
    created_at TIMESTAMP(6),
    PRIMARY KEY (id)
);

CREATE TABLE shop_agent (
    agent_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    login VARCHAR2(20 CHAR) NOT NULL,
    secret VARCHAR2(255 CHAR) NOT NULL,
    grade VARCHAR2(10 CHAR),
    PRIMARY KEY (agent_id)
);

CREATE TABLE shop_category (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    cat_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    name VARCHAR2(100 CHAR) NOT NULL,
    description CLOB,
    sort_order NUMBER(10),
    active NUMBER(1),
    parent_category_cat_id NUMBER(19),
    PRIMARY KEY (cat_id)
);

CREATE TABLE shop_customer (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    customer_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    first_name VARCHAR2(50 CHAR) NOT NULL,
    last_name VARCHAR2(50 CHAR) NOT NULL,
    email VARCHAR2(100 CHAR) NOT NULL,
    phone VARCHAR2(20 CHAR),
    date_of_birth DATE,
    loyalty_points NUMBER(19),
    customer_type VARCHAR2(1 CHAR),
    street VARCHAR2(200 CHAR),
    city VARCHAR2(100 CHAR),
    state VARCHAR2(50 CHAR),
    zip_code VARCHAR2(10 CHAR),
    country VARCHAR2(50 CHAR),
    vip_profile_profile_id NUMBER(19),
    PRIMARY KEY (customer_id)
);

CREATE TABLE shop_order (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    order_id VARCHAR2(36 CHAR) NOT NULL,
    order_date TIMESTAMP(6) NOT NULL,
    total_amount NUMBER(14,2),
    status VARCHAR2(3 CHAR),
    payment_method VARCHAR2(2 CHAR),
    street VARCHAR2(200 CHAR),
    city VARCHAR2(100 CHAR),
    state VARCHAR2(50 CHAR),
    zip_code VARCHAR2(10 CHAR),
    country VARCHAR2(50 CHAR),
    notes CLOB,
    tracking_number VARCHAR2(50 CHAR),
    version NUMBER(19),
    customer_customer_id NUMBER(19),
    PRIMARY KEY (order_id)
);

CREATE TABLE shop_order_aud (
    rev NUMBER(10) NOT NULL,
    revtype NUMBER(3),
    order_id VARCHAR2(36 CHAR) NOT NULL,
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    order_date TIMESTAMP(6),
    total_amount NUMBER(14,2),
    status VARCHAR2(3 CHAR),
    payment_method VARCHAR2(2 CHAR),
    street VARCHAR2(200 CHAR),
    city VARCHAR2(100 CHAR),
    state VARCHAR2(50 CHAR),
    zip_code VARCHAR2(10 CHAR),
    country VARCHAR2(50 CHAR),
    notes CLOB,
    tracking_number VARCHAR2(50 CHAR),
    version NUMBER(19),
    customer_customer_id NUMBER(19),
    PRIMARY KEY (order_id, rev)
);

CREATE TABLE shop_order_item (
    order_item_id VARCHAR2(36 CHAR) NOT NULL,
    order_order_id VARCHAR2(36 CHAR),
    item_seq NUMBER(10),
    quantity NUMBER(10) NOT NULL,
    unit_price NUMBER(12,2) NOT NULL,
    discount NUMBER(8,2),
    product_product_id VARCHAR2(36 CHAR),
    PRIMARY KEY (order_item_id)
);

CREATE TABLE shop_products (
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    product_id VARCHAR2(36 CHAR) NOT NULL,
    name VARCHAR2(200 CHAR) NOT NULL,
    sku VARCHAR2(50 CHAR) NOT NULL,
    description CLOB,
    price NUMBER(12,2) NOT NULL,
    cost_price NUMBER(12,2),
    stock_quantity NUMBER(10),
    weight BINARY_FLOAT,
    rating BINARY_DOUBLE,
    active NUMBER(1),
    launch_date DATE,
    last_restocked TIMESTAMP(6),
    uuid VARCHAR2(36 CHAR),
    metadata CLOB,
    thumbnail VARCHAR2(500 CHAR),
    manual_content CLOB,
    metadata_raw JSON,
    old_payload JSON,
    custom_xml XMLTYPE,
    force_long CLOB,
    tags VARCHAR2(255 CHAR),
    category_cat_id NUMBER(19),
    PRIMARY KEY (product_id)
);

CREATE TABLE shop_products_aud (
    rev NUMBER(10) NOT NULL,
    revtype NUMBER(3),
    product_id VARCHAR2(36 CHAR) NOT NULL,
    created_by VARCHAR2(50 CHAR),
    create_date TIMESTAMP(6),
    last_modified_by VARCHAR2(50 CHAR),
    last_modified_date TIMESTAMP(6),
    name VARCHAR2(200 CHAR),
    sku VARCHAR2(50 CHAR),
    description CLOB,
    price NUMBER(12,2),
    cost_price NUMBER(12,2),
    stock_quantity NUMBER(10),
    weight BINARY_FLOAT,
    rating BINARY_DOUBLE,
    active NUMBER(1),
    launch_date DATE,
    last_restocked TIMESTAMP(6),
    uuid VARCHAR2(36 CHAR),
    metadata CLOB,
    thumbnail VARCHAR2(500 CHAR),
    manual_content CLOB,
    metadata_raw JSON,
    old_payload JSON,
    custom_xml XMLTYPE,
    force_long CLOB,
    tags VARCHAR2(255 CHAR),
    category_cat_id NUMBER(19),
    PRIMARY KEY (product_id, rev)
);

CREATE TABLE shop_ticket (
    ticket_id VARCHAR2(36 CHAR) NOT NULL,
    subject VARCHAR2(100 CHAR) NOT NULL,
    status VARCHAR2(3 CHAR),
    billing VARCHAR2(3 CHAR),
    total NUMBER(14,2),
    agent_agent_id NUMBER(19),
    PRIMARY KEY (ticket_id)
);

CREATE TABLE shop_ticket_entry (
    entry_id VARCHAR2(36 CHAR) NOT NULL,
    ticket_ticket_id VARCHAR2(36 CHAR),
    hours NUMBER(10) NOT NULL,
    rate NUMBER(12,2),
    amount NUMBER(14,2),
    product_product_id VARCHAR2(36 CHAR),
    PRIMARY KEY (entry_id)
);

CREATE TABLE shop_vip_profile (
    profile_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    tier VARCHAR2(20 CHAR),
    discount_rate BINARY_DOUBLE,
    enroll_date DATE,
    customer_customer_id NUMBER(19),
    PRIMARY KEY (profile_id)
);

CREATE TABLE shop_outbox (
    id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    aggregate_type VARCHAR2(100 CHAR) NOT NULL,
    aggregate_id VARCHAR2(200 CHAR),
    event_type VARCHAR2(300 CHAR) NOT NULL,
    payload CLOB NOT NULL,
    occurred_on TIMESTAMP(6) WITH TIME ZONE,
    recorded_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    published_at TIMESTAMP(6) WITH TIME ZONE,
    attempts NUMBER(10) NOT NULL,
    last_error VARCHAR2(500 CHAR),
    PRIMARY KEY (id)
);

